describe('Onboarding Tour Modal', () => {
  beforeEach(() => {
    cy.visit('/onboarding');
  });

  it('should navigate through onboarding tour steps successfully', () => {
    // Open the onboarding tour modal
    cy.get('[data-testid="onboarding-modal-trigger"]').click();
    cy.get('[data-testid="onboarding-modal"]').should('be.visible');

    // Verify initial step is displayed
    cy.get('[data-testid="onboarding-step-1"]').should('be.visible');
    cy.get('[data-testid="step-1-title"]').should('contain', 'Welcome to Our App');

    // Verify step content is displayed
    cy.get('[data-testid="step-1-content"]').should('be.visible');
    cy.get('[data-testid="step-1-content"]').should('contain', 'This is the first step of the onboarding tour.');

    // Click the next button to advance to the next step
    cy.get('[data-testid="onboarding-next-button"]').click();

    // Verify second step is now visible
    cy.get('[data-testid="onboarding-step-2"]').should('be.visible');
    cy.get('[data-testid="step-2-title"]').should('contain', 'Create Account');

    // Verify step content is displayed
    cy.get('[data-testid="step-2-content"]').should('be.visible');
    cy.get('[data-testid="step-2-content"]').should('contain', 'Enter your email and password to create an account.');

    // Click the next button to advance to the final step
    cy.get('[data-testid="onboarding-next-button"]').click();

    // Verify final step is visible
    cy.get('[data-testid="onboarding-step-3"]').should('be.visible');
    cy.get('[data-testid="step-3-title"]').should('contain', 'Complete Onboarding');

    // Verify step content is displayed
    cy.get('[data-testid="step-3-content"]').should('be.visible');
    cy.get('[data-testid="step-3-content"]').should('contain', 'Complete your profile to finish the onboarding process.');

    // Verify close button is visible
    cy.get('[data-testid="onboarding-close-button"]').should('be.visible');

    // Close the modal
    cy.get('[data-testid="onboarding-close-button"]').click();

    // Verify modal is closed
    cy.get('[data-testid="onboarding-modal"]').should('not.exist');
  });

  it('should handle edge case when user clicks next button before all steps are visible', () => {
    // Open the onboarding tour modal
    cy.get('[data-testid="onboarding-modal-trigger"]').click();
    cy.get('[data-testid="onboarding-modal"]').should('be.visible');

    // Verify initial step is displayed
    cy.get('[data-testid="onboarding-step-1"]').should('be.visible');

    // Click the next button before step 2 is visible
    cy.get('[data-testid="onboarding-next-button"]').click();

    // Verify step 2 is not visible (should be skipped)
    cy.get('[data-testid="onboarding-step-2"]').should('not.exist');

    // Verify step 3 is still visible
    cy.get('[data-testid="onboarding-step-3"]').should('be.visible');

    // Verify step content is displayed
    cy.get('[data-testid="step-3-content"]').should('be.visible');

    // Verify close button is still visible
    cy.get('[data-testid="onboarding-close-button"]').should('be.visible');

    // Close the modal
    cy.get('[data-testid="onboarding-close-button"]').click();

    // Verify modal is closed
    cy.get('[data-testid="onboarding-modal"]').should('not.exist');
  });
});
